      const revealElements = document.querySelectorAll('[data-reveal]');
      revealElements.forEach(el => {
        const observer = new IntersectionObserver((entries, observer) => {
          entries.forEach(entry => {
            if (entry.isIntersecting) {
              entry.target.classList.add('reveal');
              observer.unobserve(entry.target);
            }
          });
        }, { threshold: 0.5 });
        observer.observe(el);
      });

      // Hover parallax effects
      const parallaxElements = document.querySelectorAll('[data-parallax]');
      parallaxElements.forEach(el => {
        const observer = new IntersectionObserver((entries, observer) => {
          entries.forEach(entry => {
            if (entry.isIntersecting) {
              entry.target.style.transform = `translateY(${entry.intersectionRatio * -60}px)`;
              observer.unobserve(entry.target);
            }
          });
        }, { threshold: 0.5 });
        observer.observe(el);
      });

      // Smooth transitions on interactive elements
      const interactiveElements = document.querySelectorAll('.cta, .feature .cta');
      interactiveElements.forEach(el => {
        el.addEventListener('mouseenter', () => {
          el.style.transition = 'background 0.3s ease, transform 0.3s ease';
        });
        el.addEventListener('mouseleave', () => {
          el.style.transition = 'none';
        });
      });

      // Counter animations
      const counterElements = document.querySelectorAll('[data-counter]');
      counterElements.forEach(el => {
        let count = 0;
        const target = parseInt(el.getAttribute('data-counter-target'), 10);
        const increment = Math.floor(target / 1000);
        const interval = setInterval(() => {
          count += increment;
          if (count >= target) {
            clearInterval(interval);
            el.textContent = `${target}`;
          } else {
            el.textContent = count;
          }
        }, 10);
      });

      // Typing/text-scramble effects
      const typeElements = document.querySelectorAll('[data-type]');
      typeElements.forEach(el => {
        let index = 0;
        const text = el.textContent;
        el.textContent = '';
        const interval = setInterval(() => {
          el.textContent += text[index];
          index = (index + 1) % text.length;
          if (index === 0) {
            clearInterval(interval);
            el.textContent = text;
          }
        }, 200);
      });

      // 3D card tilt effects on hover
      const tiltElements = document.querySelectorAll('[data-tilt]');
      tiltElements.forEach(el => {
        el.addEventListener('mouseenter', () => {
          el.style.transform = `rotateX(5deg) rotateY(5deg)`;
        });
        el.addEventListener('mouseleave', () => {
          el.style.transform = `rotateX(0deg) rotateY(0deg)`;
        });
      });

      // Ripple effects on button clicks
      const rippleElements = document.querySelectorAll('.cta, .feature .cta');
      rippleElements.forEach(el => {
        el.addEventListener('click', () => {
          const ripple = document.createElement('div');
          ripple.classList.add('ripple');
          el.appendChild(ripple);
          setTimeout(() => ripple.remove(), 300);
        });
      });

      // Particle/gradient animated backgrounds for hero sections
      const particleElements = document.querySelectorAll('[data-particle]');
      particleElements.forEach(el => {
        const particle = document.createElement('div');
        particle.classList.add('particle');
